// These tests were generated by an agent

package lzss

import (
	"bytes"
	"crypto/sha1"
	"encoding/hex"
	"strings"
	"testing"
)

var vectors = []struct {
	name, data, lzss18, lzss10 string
}{
	{"empty", "", "ff", "ffffffffffffffffffff"},
	{"short", "ab", "ff6162ff", "ff6162ffffffffffffffffffff"},
	{"zeros", strings.Repeat("\x00", 40), "e7000000eeff000f00ff",
		"ff0000000000000000c7000000eef7f8f70206ffffffffffffffffffff"},
	{"period2", strings.Repeat("ab", 10), "ef61626162eefdff",
		"ff6162616261626162ef61626162eef5ffffffffffffffffffff"},
	{"nearest", "abcd1abcd2abcd", "5f6162636431eef132f3f1ff",
		"ff6162636431616263ff643261626364ffffffffffffffffffff"},
	{"text", "the quick brown fox jumps over the lazy dog; the quick brown fox again",
		"ff7468652071756963ff6b2062726f776e20ff666f78206a756d707f73206f76657220eef1ff6c617a7920646f67f93b0c02f2fd616761696eff",
		"ff7468652071756963ff6b2062726f776e20ff666f78206a756d707f73206f76657220eef1ff6c617a7920646f67f13b0c02f2f7fcf361676169ff6effffffffffffffffffff"},
	{"into-fill", "\xff\xff\xffabc\xff", "bfffffff616263eef0ff", "ffffffff616263ffffe7ffffffeef0eef0ff"},
	{"group-end", "abcdefgh", "ff6162636465666768ff", "ff6162636465666768ffffffffffffffffffff"},
}

func TestVectors(t *testing.T) {
	for _, v := range vectors {
		for _, c := range []struct {
			p    Profile
			want string
		}{{Lzss18, v.lzss18}, {Lzss10, v.lzss10}} {
			got := hex.EncodeToString(Encode([]byte(v.data), c.p))
			if got != c.want {
				t.Errorf("%s %s: Encode = %s, want %s", v.name, c.p.Name, got, c.want)
			}
			packed, _ := hex.DecodeString(c.want)
			data, err := Decode(packed, len(v.data))
			if err != nil || string(data) != v.data {
				t.Errorf("%s %s: Decode = %q, %v", v.name, c.p.Name, data, err)
			}
		}
	}
}

func lcgBytes(n int) []byte {
	x, out := uint32(72), make([]byte, n)
	for i := range out {
		x = x*1103515245 + 12345
		out[i] = byte(x >> 16)
	}
	return out
}

func TestMixed(t *testing.T) {
	r := lcgBytes(3000)
	var mixed []byte
	mixed = append(mixed, r...)
	for i := 0; i < 3; i++ {
		mixed = append(mixed, r[1000:2000]...)
	}
	mixed = append(mixed, make([]byte, 500)...)
	mixed = append(mixed, bytes.Repeat([]byte("ab"), 300)...)
	mixed = append(mixed, r...)
	sum := func(b []byte) string { s := sha1.Sum(b); return hex.EncodeToString(s[:]) }
	if got := sum(mixed); got != "ec4f04cd9a97aea6611781982d1a8aecd734ed09" {
		t.Fatalf("input %s", got)
	}
	for _, c := range []struct {
		p    Profile
		size int
		sha  string
	}{{Lzss18, 6242, "eb281eaa8adce8ede887075a5ab770de2493d432"},
		{Lzss10, 6741, "fcddf14b5583f9b7b96c1fd33fe1da37f729e6a9"}} {
		packed := Encode(mixed, c.p)
		if len(packed) != c.size || sum(packed) != c.sha {
			t.Errorf("%s: %d bytes, sha1 %s; want %d, %s", c.p.Name, len(packed), sum(packed), c.size, c.sha)
		}
		data, err := Decode(packed, len(mixed))
		if err != nil || !bytes.Equal(data, mixed) {
			t.Errorf("%s: round trip failed: %v", c.p.Name, err)
		}
	}
}

func TestDecodeShortStream(t *testing.T) {
	packed := Encode([]byte("the quick brown fox"), Lzss18)
	for _, cut := range []int{0, 1, len(packed) - 3} {
		if _, err := Decode(packed[:cut], 19); err == nil {
			t.Errorf("cut at %d: no error", cut)
		}
	}
}

func TestDecodeStopsAtSize(t *testing.T) {
	for _, p := range []Profile{Lzss18, Lzss10} {
		data := []byte("abcde")
		got, err := Decode(Encode(data, p), len(data))
		if err != nil || !bytes.Equal(got, data) {
			t.Errorf("%s: %q, %v", p.Name, got, err)
		}
	}
}
